import re

def parse_json(text):
    pos = [0]
    def skip_space():
        while pos[0] < len(text) and text[pos[0]] in ' \t\r\n':
            pos[0] += 1
    def parse_string():
        pos[0] += 1
        chars = []
        escapes = {'"': '"', '\\': '\\', '/': '/', 'b': '\b', 'f': '\f', 'n': '\n', 'r': '\r', 't': '\t'}
        while pos[0] < len(text):
            char = text[pos[0]]
            pos[0] += 1
            if char == '"':
                return ''.join(chars)
            if char != '\\':
                chars.append(char)
                continue
            char = text[pos[0]]
            pos[0] += 1
            if char == 'u':
                chars.append(chr(int(text[pos[0]:pos[0] + 4], 16)))
                pos[0] += 4
            else:
                chars.append(escapes[char])
        raise ValueError('Unterminated JSON string')
    def parse_value():
        skip_space()
        char = text[pos[0]]
        if char == '"':
            return parse_string()
        if char == '[':
            pos[0] += 1
            result = []
            skip_space()
            if text[pos[0]] == ']':
                pos[0] += 1
                return result
            while True:
                result.append(parse_value())
                skip_space()
                char = text[pos[0]]
                pos[0] += 1
                if char == ']':
                    return result
        if char == '{':
            pos[0] += 1
            result = {}
            skip_space()
            if text[pos[0]] == '}':
                pos[0] += 1
                return result
            while True:
                skip_space()
                key = parse_string()
                skip_space()
                pos[0] += 1
                result[key] = parse_value()
                skip_space()
                char = text[pos[0]]
                pos[0] += 1
                if char == '}':
                    return result
        if text.startswith('true', pos[0]):
            pos[0] += 4
            return True
        if text.startswith('false', pos[0]):
            pos[0] += 5
            return False
        if text.startswith('null', pos[0]):
            pos[0] += 4
            return None
        match = re.match(r'-?(?:0|[1-9][0-9]*)(?:\.[0-9]+)?(?:[eE][+-]?[0-9]+)?', text[pos[0]:])
        if not match:
            raise ValueError('Invalid JSON value')
        token = match.group(0)
        pos[0] += len(token)
        return float(token) if any(mark in token for mark in '.eE') else int(token)
    result = parse_value()
    skip_space()
    if pos[0] != len(text):
        raise ValueError('Extra data after JSON value')
    return result

