import re

def read_json(text):
    pattern = re.compile(r'\s*("(?:\\.|[^"\\])*"|-?(?:0|[1-9]\d*)(?:\.\d+)?(?:[eE][+-]?\d+)?|true|false|null|[{}\[\],:])')
    tokens = []
    pos = 0
    while pos < len(text):
        match = pattern.match(text, pos)
        if not match:
            if text[pos:].strip() == "":
                break
            raise ValueError("Invalid JSON")
        tokens.append(match.group(1))
        pos = match.end()
    index = [0]

    def take():
        token = tokens[index[0]]
        index[0] += 1
        return token

    def string_value(raw):
        result = []
        i = 1
        while i < len(raw) - 1:
            char = raw[i]
            if char != "\\":
                result.append(char)
                i += 1
                continue
            i += 1
            char = raw[i]
            escapes = {'"': '"', '\\': '\\', '/': '/', 'b': '\b', 'f': '\f', 'n': '\n', 'r': '\r', 't': '\t'}
            if char == "u":
                result.append(chr(int(raw[i + 1:i + 5], 16)))
                i += 5
            else:
                result.append(escapes[char])
                i += 1
        return "".join(result)

    def value():
        token = take()
        if token == "[":
            result = []
            if tokens[index[0]] == "]":
                take()
                return result
            while True:
                result.append(value())
                separator = take()
                if separator == "]":
                    return result
                if separator != ",":
                    raise ValueError("Invalid JSON")
        if token == "{":
            result = {}
            if tokens[index[0]] == "}":
                take()
                return result
            while True:
                key = string_value(take())
                if take() != ":":
                    raise ValueError("Invalid JSON")
                result[key] = value()
                separator = take()
                if separator == "}":
                    return result
                if separator != ",":
                    raise ValueError("Invalid JSON")
        if token.startswith('"'):
            return string_value(token)
        if token == "true":
            return True
        if token == "false":
            return False
        if token == "null":
            return None
        if "." in token or "e" in token.lower():
            return float(token)
        return int(token)

    result = value()
    if index[0] != len(tokens):
        raise ValueError("Invalid JSON")
    return result

